const item = $input.item;
const binaryKeys = Object.keys(item.binary ?? {});
if (binaryKeys.length !== 1) {
  throw new Error('Submit exactly one screenshot file.');
}

const screenshotProperty = binaryKeys[0];
const screenshot = item.binary[screenshotProperty];
return [{
  json: {
    screenshotProperty,
    originalFileName: screenshot.fileName || 'screenshot.png',
    mimeType: screenshot.mimeType || 'image/png',
    errorLogs: item.json['Error logs'] || '',
    projectKey: String(item.json['Jira project key'] || '').trim().toUpperCase()
  },
  binary: item.binary
}];

const item = $input.item;
const screenshot = item.binary?.[item.json.screenshotProperty];
if (!screenshot?.data) throw new Error('Screenshot binary data is unavailable.');

return [{
  json: {
    ...item.json,
    imageDataUrl: `data:${item.json.mimeType};base64,${screenshot.data}`
  },
  binary: item.binary
}];

const source = $('Screenshot to Base64').item.json;
const content = $input.item.json?.choices?.[0]?.message?.content;
if (!content) throw new Error('Groq did not return a vision response.');

const match = String(content).match(/\{[\s\S]*\}/);
if (!match) throw new Error('Groq response did not contain a JSON object.');
const report = JSON.parse(match[0]);
const steps = Array.isArray(report.steps_to_reproduce) ? report.steps_to_reproduce : [];
const clues = Array.isArray(report.visual_clues) ? report.visual_clues : [];
const description = [
  `h2. Description\n${report.description || 'Not provided.'}`,
  `h2. Steps to Reproduce\n${steps.length ? steps.map((step, index) => `${index + 1}. ${step}`).join('\n') : 'Not provided from available evidence.'}`,
  `h2. Expected Behavior\n${report.expected_behavior || 'Not provided.'}`,
  `h2. Actual Behavior\n${report.actual_behavior || 'Not provided.'}`,
  `h2. Environment\n${report.environment || 'Unknown.'}`,
  `h2. Severity\n${report.severity || 'Minor'}`,
  `h2. Visual Clues\n${clues.length ? clues.map(clue => `* ${clue}`).join('\n') : 'None identified.'}`,
  `h2. Error Logs\n${source.errorLogs || 'None provided.'}`,
  '_Automated draft generated from screenshot analysis. Please review before triage._'
].join('\n\n');

return [{ json: { ...source, summary: `[Bug] ${report.title || 'UI issue detected'}`.slice(0, 255), description, severity: report.severity || 'Minor' } }];

const createdIssue = $input.item.json;
const source = $('Screenshot to Base64').item;
const binary = source.binary;
const screenshotProperty = source.json.screenshotProperty;
if (!binary?.[screenshotProperty]) throw new Error('Cannot retrieve original screenshot for attachment.');

return [{
  json: { issueKey: createdIssue.key, issueUrl: createdIssue.self, fileName: source.json.originalFileName },
  binary: { screenshot: binary[screenshotProperty] }
}];
